import{b as t,I as d,g as o,j as r}from"./chunks/framework.CrSplIeq.js";const p=JSON.parse('{"title":"Environment Variables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),a={name:"guide/configuration.md"};function i(c,e,s,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h1><p>Variables for the <code>gatelin</code> container. Required variables are validated at boot — the process refuses to start if any are missing or invalid.</p><h2 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;Required&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>APP_NAME</code></td><td>Application name used to build downstream service URLs (<code>{APP_NAME}-{serviceName}-{ENV_NAME}</code>)</td></tr><tr><td><code>ENV_NAME</code></td><td>Environment name, e.g. <code>local</code>, <code>staging</code>, <code>prod</code></td></tr><tr><td><code>PWD_CHECK_URL</code></td><td>Credential-check endpoint of your password service, ending in <code>/pwd/compare</code>. For mid-login challenges Gatelin also derives <code>{base}/pwd/challenges</code>, <code>{base}/pwd/trusted-devices/verify</code>, and <code>{base}/pwd/login-tickets/redeem</code> from the same base. See the <a href="./api-sessions.html#password-service-contract">Sessions contract</a></td></tr><tr><td><code>USER_SEARCH_URL</code></td><td>URL of the user microservice search endpoint (login looks up users by email)</td></tr><tr><td><code>DB_HOST</code></td><td>Hostname of the PostgreSQL container</td></tr><tr><td><code>DB_NAME</code></td><td>Database name (default: <code>gatelin</code>)</td></tr><tr><td><code>DB_USER</code></td><td>Database user for Gatelin</td></tr><tr><td><code>DB_PWD</code></td><td>Database password for Gatelin</td></tr><tr><td><code>TOKEN_SECRET</code></td><td>Secret used to sign/verify JWT tokens, at least 32 characters</td></tr><tr><td><code>SERVICE_NAME</code></td><td>Container hostname of the Gatelin service (used for logs)</td></tr><tr><td><code>ACCESS_TOKEN_DURATION</code></td><td>Access token lifetime in seconds (default: <code>600</code>)</td></tr><tr><td><code>REFRESH_TOKEN_DURATION</code></td><td>Refresh token lifetime in seconds (default: <code>86400</code>)</td></tr></tbody></table><h2 id="optional" tabindex="-1">Optional <a class="header-anchor" href="#optional" aria-label="Permalink to &quot;Optional&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PORT</code></td><td><code>3000</code></td><td>Port Gatelin listens on; also used as the port in downstream service URLs</td></tr><tr><td><code>SERVER_SCHEME</code></td><td><code>http://</code></td><td>Scheme used in internal downstream URLs</td></tr><tr><td><code>TZ</code></td><td>—</td><td>Container timezone</td></tr><tr><td><code>SESSION_RATE_LIMIT_MAX</code></td><td><code>20</code></td><td>Max login/refresh attempts per IP per 15 minutes</td></tr><tr><td><code>ADMIN_RATE_LIMIT_MAX</code></td><td><code>300</code></td><td>Max admin API requests per IP per minute</td></tr><tr><td><code>UPSTREAM_TIMEOUT_MS</code></td><td><code>30000</code></td><td>Idle timeout for outbound HTTP calls to microservices. Disabled for Server-Sent Events (<code>Accept</code> or upstream <code>Content-Type</code> of <code>text/event-stream</code>). WebSocket handshake uses this value until <code>101</code>; the piped socket has no idle timeout.</td></tr><tr><td><code>REFRESH_TOKEN_COOKIE</code></td><td>—</td><td>When truthy, refresh tokens are also set as an httpOnly cookie (via toker-express)</td></tr><tr><td><code>REFRESH_TOKEN_COOKIE_NAME</code></td><td><code>refreshToken</code></td><td>Name of the refresh-token cookie</td></tr><tr><td><code>REFRESH_TOKEN_COOKIE_SAMESITE</code></td><td><code>strict</code></td><td>Cookie <code>SameSite</code> (<code>strict</code>, <code>lax</code>, or <code>none</code>)</td></tr><tr><td><code>REFRESH_TOKEN_COOKIE_HTTPS_ONLY</code></td><td><code>true</code></td><td>Cookie <code>Secure</code> flag; set to <code>false</code> for plain-HTTP local stacks</td></tr><tr><td><code>CSRF_COOKIE_NAME</code></td><td><code>csrfToken</code></td><td>Name of the CSRF double-submit cookie</td></tr></tbody></table><h2 id="admin-ui" tabindex="-1">Admin UI <a class="header-anchor" href="#admin-ui" aria-label="Permalink to &quot;Admin UI&quot;">​</a></h2><p>The Angular admin is built into the <code>gatelin</code> image and served only when <code>ADMIN_PORT</code> is set.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ADMIN_PORT</code></td><td>unset (disabled)</td><td>Port the admin UI listens on. Unset to disable the admin UI.</td></tr><tr><td><code>ADMIN_BASE_PATH</code></td><td><code>/admin</code></td><td>Path prefix for the admin UI. Rewritten into <code>&lt;base href&gt;</code> at runtime — no Angular rebuild required. Must match your reverse-proxy rule.</td></tr><tr><td><code>ADMIN_PASSWORD_RECOVERY_URL</code></td><td>unset</td><td>When set (e.g. <code>/api/pwd/web/recover</code>), the login page shows a “Forgotten password ?” link. Injected at runtime into <code>window.__GATELIN_ADMIN__</code> (dev entrypoint + prod <code>admin-server</code>). Leave empty to hide it. In the local Compose stack, Traefik routes <code>/api/pwd</code> to the <code>ms_pwd</code> mock, which serves stand-in recovery and mid-login challenge pages under <code>/pwd/web/*</code>.</td></tr></tbody></table><blockquote><p>Docker Compose examples often set <code>ADMIN_BASE_PATH=/gatelin</code>. That is an explicit override; the code default when the variable is unset remains <code>/admin</code>.</p></blockquote><h2 id="database-migration-service" tabindex="-1">Database migration service <a class="header-anchor" href="#database-migration-service" aria-label="Permalink to &quot;Database migration service&quot;">​</a></h2><p>These apply to the <code>gatelin-migration</code> container (<code>dwtechs/gatelin-migration</code>):</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>LIQUIBASE_COMMAND_USERNAME</code></td><td>✅</td><td>PostgreSQL superuser used by Liquibase</td></tr><tr><td><code>LIQUIBASE_COMMAND_PASSWORD</code></td><td>✅</td><td>Password for the Liquibase superuser</td></tr><tr><td><code>DB_HOST</code></td><td>✅</td><td>Hostname of the PostgreSQL container</td></tr><tr><td><code>DB_PORT</code></td><td>⬜</td><td>Port of the PostgreSQL container (default: <code>5432</code>)</td></tr><tr><td><code>DB_NAME</code></td><td>✅</td><td>Database name to create and migrate</td></tr><tr><td><code>DB_USER</code></td><td>✅</td><td>Application database user to create</td></tr><tr><td><code>DB_PWD</code></td><td>✅</td><td>Password for the application database user</td></tr><tr><td><code>UPDATE</code></td><td>✅</td><td>Set to <code>1</code> to run the full migration</td></tr><tr><td><code>ROLLBACK</code></td><td>⬜</td><td>Number of changesets to roll back (used instead of <code>UPDATE</code>)</td></tr><tr><td><code>SNAPSHOT</code></td><td>⬜</td><td>Path to the reference snapshot file</td></tr><tr><td><code>LIQUIBASE_LOG_LEVEL</code></td><td>⬜</td><td>Liquibase log verbosity, e.g. <code>INFO</code>, <code>DEBUG</code></td></tr><tr><td><code>LIQUIBASE_COMMAND_CONTEXTS</code></td><td>⬜</td><td>Liquibase contexts to apply during migration</td></tr><tr><td><code>TZ</code></td><td>⬜</td><td>Timezone</td></tr></tbody></table><h2 id="jwt-cookie-flow" tabindex="-1">JWT &amp; Cookie Flow <a class="header-anchor" href="#jwt-cookie-flow" aria-label="Permalink to &quot;JWT &amp; Cookie Flow&quot;">​</a></h2><ol><li>User logs in via <code>POST /gatelin/sessions</code> with <code>{ email, pwd }</code>.</li><li>Gatelin looks up the user via <code>USER_SEARCH_URL</code>, then verifies the password via <code>PWD_CHECK_URL</code> (any password service implementing the <a href="./api-sessions.html#password-service-contract">Sessions contract</a>; <a href="https://github.com/dwtechs/Foxnox" target="_blank" rel="noreferrer">Foxnox</a> is one example).</li><li>If the password service reports lockout, expiry, or 2FA without a trusted device, Gatelin returns <strong>202</strong> with <code>{ challengeRequired, kind, url }</code> instead of a session. The browser completes the challenge on the password service, comes back with <code>?ticket=…</code>, and the client calls <code>POST /gatelin/sessions/resume</code>. Services that only check passwords never trigger this step.</li><li>Otherwise (or after a successful resume), Gatelin issues a JWT access token (short-lived) and refresh token (long-lived), sets a CSRF cookie, and returns the session payload.</li><li>Client sends the access token in <code>Authorization: Bearer &lt;token&gt;</code> on subsequent requests.</li><li>When the access token expires, client calls <code>PUT /gatelin/sessions</code> with: <ul><li><code>Authorization: Bearer &lt;access_token&gt;</code> (expired tokens are accepted for refresh),</li><li>refresh token in the JSON body and/or cookie,</li><li><code>X-CSRF-Token</code> header matching the CSRF cookie,</li><li><code>credentials: &#39;include&#39;</code> so cookies are sent.</li></ul></li><li>Logout (<code>DELETE /gatelin/sessions</code>) requires the access token and CSRF header; it archives the consumer and clears cookies.</li></ol><p>See <a href="./api-sessions.html">Sessions</a> for the pwd-service contract and <a href="./frontend.html">Frontend Integration</a> for the client-side challenge/resume handling.</p><h2 id="maintenance-jobs" tabindex="-1">Maintenance Jobs <a class="header-anchor" href="#maintenance-jobs" aria-label="Permalink to &quot;Maintenance Jobs&quot;">​</a></h2><p>Gatelin runs two daily UTC cron jobs at startup:</p><table tabindex="0"><thead><tr><th>Job</th><th>Schedule</th><th>Retention</th></tr></thead><tbody><tr><td>Delete archived entities</td><td>02:00 UTC</td><td>Records archived for more than <strong>2 months</strong></td></tr><tr><td>Delete old history</td><td>03:00 UTC</td><td>Rows in <code>log.history</code> older than <strong>6 months</strong> (<code>tstamp</code> column)</td></tr></tbody></table><p>Archived entities purged: conditions (first, due to FK), then consumers, services, CORS origins, operations, resources, routes, roles, applications, scopes, and fields. Permissions are hard-deleted via the admin API and are not part of this job.</p>',20)])])}const m=t(a,[["render",i]]);export{p as __pageData,m as default};
